# الدفعة 18: «محبة الصحابة له» و«شجاعته» (طلب المستخدم 2026-11-23: الصحيح ثم الحسن): python3 data/batch18/build.py
import json
SB='صحيح — البخاري'; SM='صحيح — مسلم'
def card(i,ch,title,text,src,grade,theme,matn,narr,sharh=None,excerpt=False,same=False):
    c=dict(id=i,chapter=ch,title=title,text=text,source=src,grade=grade,theme=theme,long=len(text)>200,
           hadith=dict(matn=matn,narrator=narr,excerpt=excerpt))
    if sharh: c['sharh']=dict(text=sharh[0],source=sharh[1])
    if same: c['same']=True
    if excerpt and not same: c['abridged']=True
    return c
